#include <stdio.h>
static int find(int p[],int u)
{
    if(p[u]!=u) { p[u]=find(p,p[u]); }
    return p[u];
}
int main(void)
{
    int from[3]={1,0,0},to[3]={2,2,1},w[3]={1,2,4};
    int p[3]={0,1,2},accepted=0,total=0;
    for(int e=0;e<3;e++) {
        int a=find(p,from[e]),b=find(p,to[e]);
        if(a!=b) { p[b]=a;accepted++;total+=w[e]; }
    }
    (void)accepted;
    (void)total;
    printf("%d\n",accepted);
    return 0;
}

